import { DEFAULT_TEXT, loadText, saveText } from "./storage.js";

function getStorage() {
  try {
    return window.localStorage;
  } catch (error) {
    console.error("hello-world: localStorage is unavailable; edits will not persist", error);
    return null;
  }
}

function insertPlainText(text) {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return;
  const range = selection.getRangeAt(0);
  range.deleteContents();
  const node = document.createTextNode(text.replace(/[\r\n]+/g, " "));
  range.insertNode(node);
  range.setStartAfter(node);
  range.collapse(true);
  selection.removeAllRanges();
  selection.addRange(range);
}

function normalise(headline) {
  // Strip any stray elements (e.g. <br>) a browser may have inserted.
  if (headline.childElementCount > 0) {
    headline.textContent = headline.textContent;
  }
}

function start() {
  const headline = document.getElementById("headline");
  const storage = getStorage();

  headline.textContent = storage ? loadText(storage) : DEFAULT_TEXT;

  headline.addEventListener("input", () => {
    normalise(headline);
    if (storage) saveText(storage, headline.textContent);
  });

  headline.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      headline.blur();
    }
  });

  headline.addEventListener("paste", (event) => {
    event.preventDefault();
    insertPlainText(event.clipboardData?.getData("text/plain") ?? "");
    headline.dispatchEvent(new Event("input", { bubbles: true }));
  });

  headline.addEventListener("blur", () => {
    if (headline.textContent.trim() === "") {
      headline.textContent = DEFAULT_TEXT;
    }
  });
}

start();

export const DEFAULT_TEXT = "hello world";
export const STORAGE_KEY = "hello-world:text";

export function loadText(storage) {
  try {
    const value = storage.getItem(STORAGE_KEY);
    return value === null ? DEFAULT_TEXT : value;
  } catch (error) {
    console.error(`hello-world: failed to load text from storage key "${STORAGE_KEY}"`, error);
    return DEFAULT_TEXT;
  }
}

export function saveText(storage, text) {
  const isBlank = text.trim() === "";
  try {
    if (isBlank) {
      storage.removeItem(STORAGE_KEY);
    } else {
      storage.setItem(STORAGE_KEY, text);
    }
  } catch (error) {
    const operation = isBlank ? "remove" : "save";
    console.error(`hello-world: failed to ${operation} text at storage key "${STORAGE_KEY}"`, error);
  }
}

{"ts": "2026-10-11T20:39:20.581190+00:00", "run_id": "20261011-202303", "title": "Require the implementer to self-review against all repository contracts", "rationale": "The instruction to ignore coding standards delegates basic correctness entirely to later review, contributing to three corrective loops and substantial token use. The implementer should check the plan, architecture, standards, and validation requirements before declaring completion, especially error paths and asynchronous state transitions.", "evidence": "agents/implementer.md says “Ignore coding-standards documents.” Despite an initial claim of 18 passing tests and Playwright E2E passing 22/22 three times, review-2.md found an uncaught malformed-URL process crash, an untested documented 500 path, and invalid PORT handling; review-3.md found pagehide data loss; review-4.md found a delayed-load edit-overwrite race. run-state.json records 374,196 implement-stage input tokens and three changes_requested verdicts before approval.", "proposed_change": "Update agents/implementer.md to remove the instruction to ignore coding standards. Require a pre-handoff self-review against the plan, docs/architecture.md, docs/coding-standards.md, and docs/VALIDATION.md, including explicit checks of failure boundaries, documented contracts, and overlapping asynchronous events. Require every review fix to preserve all existing acceptance criteria and to include a focused regression test or deterministic reproduction.", "decision": "approved", "note": ""}
{"ts": "2026-10-11T20:40:55.544368+00:00", "run_id": "20261011-202303", "title": "Make plans concise, internally consistent, and validation-proportional", "rationale": "The plan over-specified incidental implementation details and exhaustive visual instrumentation while containing a contradictory persistence contract. This increased implementation cost and made a later reviewer suggestion easy to misapply.", "evidence": "plan.md calls data/hello.json a JSON file but step 2 and A3 require its contents to be literal raw UTF-8 text. review-2.md suggested either writing JSON or renaming the artifact; the loop-3 implementation then changed storage to JSON, and review-3.md required reverting it as a major contract violation. The planner produced 13,680 output tokens, while the implementer created three throwaway Playwright scripts, ran E2E three times, and reported 34 visual checks for a small hello-world app.", "proposed_change": "Update agents/planner.md to require a final consistency audit across fixed decisions, file formats, contracts, tests, and acceptance criteria. Instruct it to distinguish normative requirements from illustrative implementation suggestions, avoid hard-coding incidental environment versions or excessive test mechanics, and choose the smallest proportional validation set that proves the user-visible outcome.", "decision": "approved", "note": ""}
{"ts": "2026-10-11T20:43:43.411927+00:00", "run_id": "20261011-202303", "title": "Require reviewer remediation advice to preserve higher-priority contracts", "rationale": "A reviewer finding should not offer a fix that conflicts with an explicit acceptance criterion. Reviews should also not approve while leaving a concrete, readily fixable inconsistency in a protected architecture document.", "evidence": "review-2.md’s store.js finding offered “either write JSON or name the artifact hello.txt,” although plan.md A3 explicitly required literal file contents and the fixed file layout required data/hello.json. The resulting JSON implementation caused the major finding in review-3.md. review-5.md approved while identifying that docs/architecture.md claimed four server-side modules but listed only three; that defect remains in /home/ian/hello-world/docs/architecture.md after merge.", "proposed_change": "Update agents/reviewer.md to rank the request and explicit acceptance criteria above incidental naming concerns, and to cross-check every proposed remediation against the full plan before suggesting it. Require changes_requested for any actionable contract or protected-document inaccuracy; reserve non-blocking minor findings for genuinely advisory issues that need no code or documentation change.", "decision": "approved", "note": ""}
{"ts": "2026-10-11T20:45:15.643336+00:00", "run_id": "20261011-202303", "title": "Add a mandatory process-cleanup command preflight", "rationale": "The existing prohibition was ignored, and a pattern-based kill terminated the agent itself. A concrete preflight checklist is warranted because this failure wasted an invocation and could endanger the factory process.", "evidence": "events.jsonl around lines 36580–36626 shows the implementer issuing `pkill -f \"node main.js\"`; the invocation immediately ended with return code 143 and `failure: \"pi exited with code 143\"`. run-state.json records implement loop 1 as failed with 39,501 input and 27,186 output tokens. The command directly violated agents/implementer.md’s cleanup rule.", "proposed_change": "Strengthen agents/implementer.md with a mandatory check before any cleanup command: only use a PID captured when starting the process or `fuser -k <known-port>/tcp`; reject commands containing pkill, killall, or process-pattern pipelines before execution. If ownership cannot be established, leave the process running and report it rather than guessing.", "decision": "approved", "note": ""}
